-- Zone Gore Overhaul, kid mode for particles: particles\set for gory effects.
-- The C++ particle blender's R4 elements (xray-monolith Blender_Particle.cpp) with this
-- mod list's shaders.xr settings for particles\set (from base:files.db0): priority 1, strict sorting off,
-- blending SET, texture clamp on. Only the pixel shader differs: zgo_particle_kid*.ps is the
-- stock one plus a discard while the shader bus lane zgo_view hides gore.
-- Generated by tools/zgo_kidfx/kidfx_pe.py shaders --write; checked by dev/shadercheck/check.sh.
-- shadercheck-parity: particles\set

function normal(shader, t_base, t_second, t_detail)
	shader:begin("deffer_particle", "zgo_particle_kid_deffer")
		:sorting(1, false)
		:fog(false)
		:zb(true, true)
		:blend(false, blend.one, blend.zero)
		:aref(false, 200)
	shader:dx10texture("s_base", t_base)
	shader:dx10sampler("smp_base"):clamp()
	shader:dx10texture("s_position", "$user$position")
	shader:dx10sampler("smp_nofilter")
end

function l_point(shader, t_base, t_second, t_detail)
	shader:begin("particle", "zgo_particle_kid")
		:sorting(1, false)
		:fog(false)
		:zb(true, true)
		:blend(false, blend.one, blend.zero)
		:aref(true, 200)
		:color_write_enable(false, false, false, false)
	shader:dx10texture("s_base", t_base)
	shader:dx10sampler("smp_base"):clamp()
	shader:dx10texture("s_position", "$user$position")
	shader:dx10sampler("smp_nofilter")
end
